parameters.jsCode:
// Cada item é a resposta do Firebase para um celular, na ordem dos destinatários.
// Se o próprio nó do Firebase quebrar (ex.: credencial do Google errada),
// chega um item só com o erro, e todos contam como falha.
const destinatarios = $('Um item por celular').all();
const respostas = $input.all();
const enviados = respostas.filter((r) => r.json.statusCode === 200).length;
const primeiraFalha = respostas.find((r) => r.json.statusCode !== 200)?.json;

// App desinstalado: o Firebase responde UNREGISTERED e a API apaga o token.
// Outros 404 (ex.: ID do projeto errado) não apagam nada.
const desinstalado = (r) =>
  (r.json.body?.error?.details ?? []).some((d) => d.errorCode === 'UNREGISTERED');
const tokensInvalidos = respostas
  .map((r, i) => (desinstalado(r) ? destinatarios[i]?.json.token : null))
  .filter(Boolean);

return [{
  json: {
    total: destinatarios.length,
    enviados,
    falhas: destinatarios.length - enviados,
    // Aparece no painel do admin para ajudar a achar o problema
    primeiroErro: primeiraFalha
      ? primeiraFalha.body?.error?.message ||
        primeiraFalha.error?.message ||
        primeiraFalha.error ||
        `HTTP ${primeiraFalha.statusCode}`
      : '',
    tokensInvalidos,
  },
}];
